SELECT pr.id AS reserveId, pr.charging_station_id AS stationId, pr.station_owner_id AS stationOwnerId, pcs.name AS stationName, ui.name AS ownerName, pr.reserve_time AS reserveTime, pr.status AS reserveStatus, pr.create_time AS createTime FROM private_station_reserve pr LEFT JOIN private_charge_station pcs ON pr.charging_station_id = pcs.id LEFT JOIN user_info ui ON pr.station_owner_id = ui.id WHERE pr.user_id = #{userId}
AND pr.status = #{status}
ORDER BY pr.create_time DESC

SELECT pr.id AS reserveId, pr.charging_station_id AS stationId, pcs.name AS stationName, pr.user_id AS reserveUserId, ui.name AS reserveUserName, pr.reserve_time AS reserveTime, pr.status AS status, pr.create_time AS createTime FROM private_station_reserve pr LEFT JOIN private_charge_station pcs ON pr.charging_station_id = pcs.id LEFT JOIN user_info ui ON pr.user_id = ui.id WHERE pr.station_owner_id = #{stationOwnerId}
AND pr.status = #{status}
ORDER BY pr.create_time DESC
